sampling policy "checkout-tail" {
  keep: status == "error" or duration > 800ms or route == "/checkout"
  window: 30s
  default_rate: 0.02
}

route "db-pool-exhaustion" {
  when: alert.name == "pool_exhaustion" and affected_hosts_pct > 25
  to: pagerduty("database-oncall"), slack("#db-incidents")
  else_to: slack("#db-watch")
}

route "payments-critical" {
  when: alert.severity == "critical" and team == "payments"
  to: oncall("payments-primary")
  escalate_after: 5m to oncall("payments-secondary")
}

from ingest_usage
| summarize cost=sum(cost_usd) by signal, retention_tier
| order by cost desc
// a typical split-stack customer, pre-migration:
